import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.G0y0PQA7.js";const i="/relio/shots/en/draw-table-dialog.png",r="/relio/shots/en/draw-relation-fk.png",m=JSON.parse('{"title":"Draw tables, columns and relationships","description":"","frontmatter":{},"headers":[],"relativePath":"en/quick/draw.md","filePath":"en/quick/draw.md"}'),s={name:"en/quick/draw.md"};function l(d,e,c,h,p,g){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="draw-tables-columns-and-relationships" tabindex="-1">Draw tables, columns and relationships <a class="header-anchor" href="#draw-tables-columns-and-relationships" aria-label="Permalink to &quot;Draw tables, columns and relationships&quot;">​</a></h1><p>Draw two tables in an empty diagram and connect them with a relationship.</p><ol><li><p><strong>New diagram</strong> — In File › New diagram (<kbd>Ctrl</kbd>+<kbd>N</kbd>), choose the database type.</p></li><li><p><strong>Place a table</strong> — Pick Table (<kbd>T</kbd>) in the palette on the left and click the canvas. The table is created and <strong>its name field opens right away</strong>. Type a name and press <kbd>Enter</kbd>. To rename it later, select the table and press <kbd>F2</kbd>.</p></li><li><p><strong>Add columns</strong> — Double-click the table (or press <kbd>Enter</kbd>) to open the table properties dialog, and add columns. As you type a physical name, candidates from the word dictionary and from other tables&#39; columns appear above the field. Pick one with <kbd>↓</kbd> and accept it with <kbd>Enter</kbd> to fill in the name, type and length at once.</p><figure class="shot" data-scene="draw-table-dialog"><img src="'+i+'" alt="Table properties dialog — the column list and suggestions while typing" loading="lazy"><figcaption>Table properties dialog — the column list and suggestions while typing</figcaption></figure></li><li><p><strong>Connect a relationship</strong> — Pick 1:N relationship (<kbd>R</kbd>) in the palette and drag from the parent table to the child table. Foreign key (FK) columns that follow the parent&#39;s primary key (PK) are created in the child automatically.</p><figure class="shot" data-scene="draw-relation-fk"><img src="'+r+'" alt="After connecting a relationship, a foreign key column appears in the child table" loading="lazy"><figcaption>After connecting a relationship, a foreign key column appears in the child table</figcaption></figure></li><li><p><strong>Undo</strong> — Every edit can be undone with <kbd>Ctrl</kbd>+<kbd>Z</kbd> and redone with <kbd>Ctrl</kbd>+<kbd>Y</kbd>.</p></li></ol><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h2><ul><li><strong>Physical and logical names</strong> — The physical name is the name the database uses (<code>MEMBER_ID</code>); the logical name is the name people read (<code>Member ID</code>). The View menu chooses which one the canvas shows.</li><li><strong>Word dictionary</strong> — Columns point to words in the word dictionary, so columns that share a word change together. Drag a word from the outline on the right onto a table on the canvas to add it as a column.</li><li><strong>Design check</strong> — Problems such as a missing primary key or a reserved word used as a name are reported while you draw, with a mark on the table header and in the problem list below. Saving and exporting are never blocked.</li></ul><p><strong>More</strong> → <a href="/relio/en/features/canvas">Canvas and palette</a> · <a href="/relio/en/features/dialogs">Properties dialogs</a> · <a href="/relio/en/features/edit">Edit</a> · <a href="/relio/en/features/check">Design check and suggestions</a></p>',6)])])}const k=a(s,[["render",l]]);export{m as __pageData,k as default};
